#!/usr/bin/env node
/**
 * AUTH HTTP LATENCY DIAGNOSTIC (SAFE)
 *
 * Measures HTTP traffic generated by ONE supabase.auth.signInWithPassword()
 * without using real credentials or printing authentication material.
 *
 * - Uses synthetic invalid credentials only (never demo/production accounts)
 * - Logs method, path template, status, TTFB, duration only
 * - Never prints email, password, tokens, API keys, Authorization, or response bodies
 *
 * Usage (from repo root):
 *   node --env-file=.env.local scripts/auth-http-latency-safe.mjs
 */

import { createClient } from "@supabase/supabase-js";

const SYNTHETIC_EMAIL = "rovexo-http-forensic-invalid@example.invalid";
const SYNTHETIC_PASSWORD = "not-a-real-credential";

function requirePublicUrl() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL;
  if (!url) {
    console.error("MISSING_PUBLIC_SUPABASE_URL");
    process.exit(1);
  }
  return url.replace(/\/$/, "");
}

function requireAnonKeyPresent() {
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || process.env.SUPABASE_ANON_KEY;
  if (!key) {
    console.error("MISSING_PUBLIC_ANON_KEY");
    process.exit(1);
  }
  return key;
}

/** Path-only URL: host → [supabase-host]; keep grant_type only. */
function safeUrl(raw) {
  try {
    const u = new URL(raw);
    const kept = new URLSearchParams();
    for (const [k, v] of u.searchParams.entries()) {
      if (/token|key|secret|password|apikey|authorization|access|refresh/i.test(k)) {
        kept.set(k, "[REDACTED]");
      } else if (k === "grant_type") {
        kept.set(k, v);
      } else {
        kept.set(k, "[omitted]");
      }
    }
    const qs = kept.toString();
    return `[supabase-host]${u.pathname}${qs ? `?${qs}` : ""}`;
  } catch {
    return "[unparseable-url]";
  }
}

const httpLog = [];
let seq = 0;
const nativeFetch = globalThis.fetch.bind(globalThis);

globalThis.fetch = async (input, init = {}) => {
  const n = ++seq;
  const method = (init.method || "GET").toUpperCase();
  const reqUrl =
    typeof input === "string"
      ? input
      : input instanceof URL
        ? input.toString()
        : input.url;
  const t0 = Date.now();
  const entry = {
    n,
    timestamp: new Date(t0).toISOString(),
    method,
    url: safeUrl(reqUrl),
    status: null,
    ttfbMs: null,
    durationMs: null,
    redirected: false,
    errorClass: null,
  };
  httpLog.push(entry);

  try {
    const res = await nativeFetch(input, init);
    entry.ttfbMs = Date.now() - t0;
    entry.status = res.status;
    entry.redirected = Boolean(res.redirected);
    const buf = await res.arrayBuffer();
    entry.durationMs = Date.now() - t0;
    const rebuilt = new Response(buf, {
      status: res.status,
      statusText: res.statusText,
      headers: res.headers,
    });
    Object.defineProperty(rebuilt, "url", { value: res.url });
    Object.defineProperty(rebuilt, "redirected", { value: res.redirected });
    Object.defineProperty(rebuilt, "type", { value: res.type });
    return rebuilt;
  } catch (e) {
    entry.durationMs = Date.now() - t0;
    entry.errorClass = e?.name || "Error";
    throw e;
  }
};

const url = requirePublicUrl();
const anon = requireAnonKeyPresent();

const supabase = createClient(url, anon, {
  auth: {
    persistSession: false,
    autoRefreshToken: false,
    detectSessionInUrl: false,
  },
});

const sdkT0 = Date.now();
const { data, error } = await supabase.auth.signInWithPassword({
  email: SYNTHETIC_EMAIL,
  password: SYNTHETIC_PASSWORD,
});
const sdkElapsedMs = Date.now() - sdkT0;

const outcome = data?.session
  ? "UNEXPECTED_SESSION"
  : error
    ? "EXPECTED_AUTH_REJECT_OR_UPSTREAM"
    : "NO_SESSION_NO_ERROR";

console.log("AUTH_HTTP_LATENCY_SAFE");
console.log(`sdk_call_count=1`);
console.log(`sdk_elapsed_ms=${sdkElapsedMs}`);
console.log(`outcome=${outcome}`);
console.log(`http_request_count=${httpLog.length}`);
console.log(`auth_error_name=${error?.name || "none"}`);
console.log(`auth_error_status=${error?.status ?? "n/a"}`);

for (const e of httpLog) {
  console.log("----------------------------");
  console.log(`HTTP Request #${e.n}`);
  console.log(`timestamp=${e.timestamp}`);
  console.log(`method=${e.method}`);
  console.log(`url=${e.url}`);
  console.log(`status=${e.status ?? "n/a"}`);
  console.log(`ttfb_ms=${e.ttfbMs ?? "n/a"}`);
  console.log(`duration_ms=${e.durationMs ?? "n/a"}`);
  console.log(`redirected=${e.redirected}`);
  if (e.errorClass) console.log(`error_class=${e.errorClass}`);
}
console.log("----------------------------");
if (httpLog.length === 1) {
  const d = httpLog[0].durationMs ?? 0;
  if (d >= 5000) {
    console.log(`CONCLUSION=C single_http delayed_ms=${d}`);
  } else {
    console.log(`CONCLUSION=A single_http duration_ms=${d}`);
  }
} else if (httpLog.length > 1) {
  console.log(`CONCLUSION=B multiple_http count=${httpLog.length}`);
} else {
  console.log("CONCLUSION=UNKNOWN zero_http");
}
